BUNDLE_EOF

echo "Bundle written: $(wc -c < $TARGET) bytes"

# Syntax check
if node -c "$TARGET"; then
  echo "PASS: JavaScript syntax valid!"
else
  echo "FAIL: Syntax error detected! Restoring backup..."
  LATEST_BAK=$(ls -t ${TARGET}.bak.* 2>/dev/null | head -1)
  if [ -n "$LATEST_BAK" ]; then
    cp "$LATEST_BAK" "$TARGET"
    echo "Restored from $LATEST_BAK"
  fi
  exit 1
fi

# Update cache buster in index.html
sed -i 's/index-paginated\.js[^"]*"/index-paginated.js?v=8"/g' "$HTML"
echo "Cache buster updated to v8"

# Show what index.html references
grep -o 'index-paginated[^"]*' "$HTML"

# Reload nginx
sudo nginx -t && sudo systemctl reload nginx
echo ""
echo "=== DEPLOYMENT COMPLETE ==="
echo "Test: https://admin.airwallexus.online"
